insert into jenis_buta_warna (id, nama, label_parsial, kelompok, deskripsi, saran) values ('NORMAL', 'Penglihatan Warna Normal', 'Normal', 'Normal', 'Mampu membedakan merah, hijau, biru, dan kuning dengan baik. Tidak ditemukan pola buta warna pada tes ini.', 'Tidak perlu tindak lanjut khusus. Ulangi skrining bila ada keluhan baru.') on conflict (id) do update set nama = excluded.nama, label_parsial = excluded.label_parsial, kelompok = excluded.kelompok, deskripsi = excluded.deskripsi, saran = excluded.saran;
insert into jenis_buta_warna (id, nama, label_parsial, kelompok, deskripsi, saran) values ('PROTANOPIA', 'Protanopia (Buta Warna Merah Total)', 'Buta Warna Parsial Merah', 'Merah-Hijau', 'Tidak ada fungsi sel kerucut merah (L-cone). Warna merah terlihat sangat gelap, seperti hitam atau coklat gelap, dan sulit dibedakan dari hijau.', 'Periksa ke dokter mata / spesialis. Tes lanjutan: anomaloskop dan Farnsworth D-15. Perhatikan rambu dan lampu lalu lintas.') on conflict (id) do update set nama = excluded.nama, label_parsial = excluded.label_parsial, kelompok = excluded.kelompok, deskripsi = excluded.deskripsi, saran = excluded.saran;
insert into jenis_buta_warna (id, nama, label_parsial, kelompok, deskripsi, saran) values ('PROTANOMALY', 'Protanomaly (Buta Warna Merah Parsial)', 'Buta Warna Parsial Merah', 'Merah-Hijau', 'Sel kerucut merah berfungsi lemah. Merah terlihat lebih gelap dan kusam, tetapi masih bisa dibedakan pada warna yang terang dan jenuh.', 'Periksa ke dokter mata untuk konfirmasi. Tes lanjutan: anomaloskop. Hindari pekerjaan yang mengandalkan merah gelap.') on conflict (id) do update set nama = excluded.nama, label_parsial = excluded.label_parsial, kelompok = excluded.kelompok, deskripsi = excluded.deskripsi, saran = excluded.saran;
insert into jenis_buta_warna (id, nama, label_parsial, kelompok, deskripsi, saran) values ('DEUTERANOPIA', 'Deuteranopia (Buta Warna Hijau Total)', 'Buta Warna Parsial Hijau', 'Merah-Hijau', 'Tidak ada fungsi sel kerucut hijau (M-cone). Hijau terlihat seperti coklat atau abu-abu dan sulit dibedakan dari merah.', 'Periksa ke dokter mata / spesialis. Tes lanjutan: anomaloskop dan Farnsworth D-15.') on conflict (id) do update set nama = excluded.nama, label_parsial = excluded.label_parsial, kelompok = excluded.kelompok, deskripsi = excluded.deskripsi, saran = excluded.saran;
insert into jenis_buta_warna (id, nama, label_parsial, kelompok, deskripsi, saran) values ('DEUTERANOMALY', 'Deuteranomaly (Buta Warna Hijau Parsial)', 'Buta Warna Parsial Hijau', 'Merah-Hijau', 'Sel kerucut hijau berfungsi lemah. Ini jenis buta warna parsial yang paling umum. Hijau dan merah sering tertukar, terutama pada warna yang pudar.', 'Periksa ke dokter mata untuk konfirmasi. Ini jenis paling umum dan biasanya tidak disadari sejak lama.') on conflict (id) do update set nama = excluded.nama, label_parsial = excluded.label_parsial, kelompok = excluded.kelompok, deskripsi = excluded.deskripsi, saran = excluded.saran;
insert into jenis_buta_warna (id, nama, label_parsial, kelompok, deskripsi, saran) values ('TRITANOPIA', 'Tritanopia (Buta Warna Biru-Kuning Total)', 'Buta Warna Parsial Biru-Kuning', 'Biru-Kuning', 'Tidak ada fungsi sel kerucut biru (S-cone). Biru terlihat seperti hijau, dan kuning terlihat seperti merah muda atau abu-abu.', 'Periksa ke dokter mata. Tritanopia jarang bawaan lahir dan lebih sering terkait kondisi mata lain, jadi perlu diperiksa lebih lanjut.') on conflict (id) do update set nama = excluded.nama, label_parsial = excluded.label_parsial, kelompok = excluded.kelompok, deskripsi = excluded.deskripsi, saran = excluded.saran;
insert into jenis_buta_warna (id, nama, label_parsial, kelompok, deskripsi, saran) values ('TRITANOMALY', 'Tritanomaly (Buta Warna Biru-Kuning Parsial)', 'Buta Warna Parsial Biru-Kuning', 'Biru-Kuning', 'Sel kerucut biru berfungsi lemah. Biru dan kuning sulit dibedakan, tetapi masih bisa dikenali pada warna yang terang.', 'Periksa ke dokter mata untuk konfirmasi dan tes lanjutan.') on conflict (id) do update set nama = excluded.nama, label_parsial = excluded.label_parsial, kelompok = excluded.kelompok, deskripsi = excluded.deskripsi, saran = excluded.saran;
insert into jenis_buta_warna (id, nama, label_parsial, kelompok, deskripsi, saran) values ('ACHROMATOPSIA', 'Achromatopsia (Buta Warna Total)', 'Buta Warna Total', 'Total', 'Tidak dapat melihat warna sama sekali; dunia terlihat hitam, putih, dan abu-abu. Sering disertai silau dan penglihatan yang kurang tajam.', 'Segera periksa ke dokter mata / spesialis. Perlu pemeriksaan menyeluruh dan kacamata khusus bila diperlukan.') on conflict (id) do update set nama = excluded.nama, label_parsial = excluded.label_parsial, kelompok = excluded.kelompok, deskripsi = excluded.deskripsi, saran = excluded.saran;
