-- Schema Supabase — Sistem Informasi Pakar Buta Warna
-- Jalankan file ini di Supabase Dashboard > SQL Editor > New query,
-- lalu klik Run. Aman diulang: semua CREATE memakai IF NOT EXISTS dan
-- semua INSERT memakai ON CONFLICT ... DO UPDATE (upsert).
-- Setelah itu isi .env dengan URL + anon key (lihat .env.example).
-- Alternatif seed lewat Node: node supabase/seed.js (butuh .env terisi).

-- ===================== TABEL =====================

create table if not exists jenis_buta_warna (
  id text primary key,
  nama text not null,
  label_parsial text default '',
  kelompok text default '',
  deskripsi text default '',
  saran text default '',
  created_at timestamptz not null default now()
);

create table if not exists gejala (
  id text primary key,
  teks text not null,
  bobot numeric not null default 0.7,
  kelompok text default 'umum',
  created_at timestamptz not null default now()
);

create table if not exists plat_ishihara (
  id text primary key,
  nomor integer not null,
  angka_benar text not null,
  angka_salah_umum text[] not null default '{}',
  kategori text not null default 'merah-hijau',
  warna_target text not null,
  warna_latar text not null,
  pasangan_warna_tertukar text not null,
  arti text default '',
  warna_angka text,
  warna_titik_latar text,
  created_at timestamptz not null default now()
);

create table if not exists aturan (
  id text primary key,
  premis text[] not null,
  konklusi text not null,
  cf numeric not null,
  penjelasan text default '',
  created_at timestamptz not null default now()
);

create table if not exists riwayat_konsultasi (
  id bigint generated always as identity primary key,
  nama text not null default 'Tanpa nama',
  umur text default '',
  tanggal timestamptz not null default now(),
  diagnosis text not null,
  diagnosis_nama text not null,
  cf numeric not null,
  hasil_json jsonb not null,
  created_at timestamptz not null default now()
);

create table if not exists detail_jawaban (
  id bigint generated always as identity primary key,
  riwayat_id bigint not null references riwayat_konsultasi(id) on delete cascade,
  jenis text not null,
  kode text not null,
  jawaban text not null,
  created_at timestamptz not null default now()
);

create index if not exists idx_detail_riwayat on detail_jawaban(riwayat_id);
create index if not exists idx_riwayat_tanggal on riwayat_konsultasi(tanggal desc);

-- ===================== ROW LEVEL SECURITY =====================
-- Untuk TUGAS/DEMO: policy terbuka untuk peran anon (baca + tulis).
-- Artinya siapa pun yang punya anon key bisa baca/tulis tabel ini.
-- Ini memang disengaja supaya aplikasi Expo bisa CRUD tanpa login.
-- UNTUK PRODUKSI: hapus policy di bawah dan ganti dengan policy yang
-- membatasi per user (misal auth.uid() = user_id) + jangan pernah pakai
-- service_role key di aplikasi mobile.

alter table jenis_buta_warna enable row level security;
alter table gejala enable row level security;
alter table plat_ishihara enable row level security;
alter table aturan enable row level security;
alter table riwayat_konsultasi enable row level security;
alter table detail_jawaban enable row level security;

-- Policy ditulis eksplisit per tabel (tanpa DO / FOREACH) supaya
-- jalan di SQL Editor Supabase tanpa error syntax 42601.
drop policy if exists "anon_all" on jenis_buta_warna;
create policy "anon_all" on jenis_buta_warna for all to anon, authenticated using (true) with check (true);
drop policy if exists "anon_all" on gejala;
create policy "anon_all" on gejala for all to anon, authenticated using (true) with check (true);
drop policy if exists "anon_all" on plat_ishihara;
create policy "anon_all" on plat_ishihara for all to anon, authenticated using (true) with check (true);
drop policy if exists "anon_all" on aturan;
create policy "anon_all" on aturan for all to anon, authenticated using (true) with check (true);
drop policy if exists "anon_all" on riwayat_konsultasi;
create policy "anon_all" on riwayat_konsultasi for all to anon, authenticated using (true) with check (true);
drop policy if exists "anon_all" on detail_jawaban;
create policy "anon_all" on detail_jawaban for all to anon, authenticated using (true) with check (true);

-- Hak akses tabel untuk peran API (anon/authenticated).
grant select, insert, update, delete on jenis_buta_warna, gejala, plat_ishihara, aturan, riwayat_konsultasi, detail_jawaban to anon, authenticated;
grant usage, select on all sequences in schema public to anon, authenticated;

